var W = (id, date, ex) => ({
  id,
  title: id,
  start_time: `${date}T12:00:00Z`,
  end_time: `${date}T13:00:00Z`,
  exercises: ex.map(([title2, sets]) => ({ title: title2, exercise_template_id: title2, sets: sets.map(([lb, reps]) => ({ type: "normal", weight_kg: toKg(lb, "lb"), reps })) }))
});
var title = (lift) => LIFTS[lift].hevy[0];
function setup(t, maxes, options = {}) {
  const opts = { ...Object.fromEntries(t.options.map((o) => [o.key, o.default])), ...options };
  const cfg = { templateId: t.id, options: opts, unit: "lb", startDate: "2026-01-01", startWeights: {}, trainingMaxes: maxes ?? t.defaults("lb").trainingMaxes, increments: {} };
  const def = t.build(opts);
  return { cfg, def };
}
function plan(def, cfg, dayId, state) {
  const i = def.days.findIndex((d) => d.id === dayId);
  expect(i).toBeGreaterThanOrEqual(0);
  const week = Number(dayId.slice(1, dayId.indexOf("D"))) - 1;
  return planDay(def, cfg, { ...state ?? initialState(def, cfg), rotations: week }, i);
}
var loads = (def, cfg, dayId, lift, k = 0) => plan(def, cfg, dayId).exercises.filter((e) => e.lift === lift)[k].sets.map((s) => s.weight);
function runAll(def, cfg) {
  let s = initialState(def, cfg);
  let n = 0;
  while (!s.complete && n < 200) {
    const p = planDay(def, cfg, s);
    const ex = p.exercises.filter((e) => LIFTS[e.lift]?.hevy.length).map((e) => [title(e.lift), e.sets.map((x) => [x.weight || 100, x.reps])]);
    s = applyWorkout(def, cfg, s, W(`w${n}`, "2026-02-01", ex), s.dayIndex);
    n++;
  }
  return { s, n };
}
var uniqueIds = (def) => {
  const ids = allSlots(def).map((x) => x.id);
  expect(new Set(ids).size).toBe(ids.length);
  expect(new Set(def.days.map((d) => d.id)).size).toBe(def.days.length);
};
